using System;using System.IO;using System.Reflection;using System.Windows.Forms;
internal static class NewMateMenuProbe {
 [STAThread]static int Main(string[] args){var cfg=PetFiles.Json.Deserialize<PetConfig>(File.ReadAllText(args[0]));using(var pet=new DesktopPet(cfg,args[0])){var flags=BindingFlags.Instance|BindingFlags.NonPublic;var menu=(ContextMenuStrip)typeof(DesktopPet).GetField("sizeMenu",flags).GetValue(pet);if(menu.Items.Count!=2||menu.Items[0].Text!="退出伴随"||menu.Items[1].Text!="打开设置")throw new Exception("Wrong configuration menu items");Console.WriteLine("PASS two exact configuration actions");menu.Items[1].PerformClick();var open=PetFiles.Json.Deserialize<System.Collections.Generic.Dictionary<string,object>>(File.ReadAllText(Path.Combine(cfg.directory,"open-chat.json")));if(Convert.ToString(open["page"])!="settings")throw new Exception("Settings navigation missing");Console.WriteLine("PASS settings emits trusted configuration navigation");typeof(DesktopPet).GetField("companion",flags).SetValue(pet,true);menu.Items[0].PerformClick();var command=PetFiles.Json.Deserialize<System.Collections.Generic.Dictionary<string,object>>(File.ReadAllText(Path.Combine(cfg.directory,"companion-command.json")));if(Convert.ToString(command["action"])!="stop-companion")throw new Exception("Companion exit missing");Console.WriteLine("PASS exit emits companion-only release command");}return 0;}
}
